//! 🧪️ Original native semantic authority and independent physical turn receipts.
use super::*;
use semio_framework_os_store_snapshot_clone::{RetainedCloneEdit,RetainedCloneEditCursor,RetainedCloneEditStep,RetainedClonePreparationFactory};
use semio_framework_os_store_one_item::{ArtifactStoreOneItemFootprint,ArtifactStoreOneItemGrant};
use semio_framework_os_store_command::HistoryLane;
use semio_framework_value_snapshot_read::SnapshotReadRegistryHandle;
use super::super::ArtifactReplayPreparationFactory;
use semio_framework_value::retained_clone::{RetainedCloneBirthDemand,retained_clone_grant_admits};
#[derive(semio_framework_value::FactoryPayloadRetirement)]
struct ScalarEdit;
struct ScalarCursor{phase:u8,inverse:ManuallyDrop<Option<Vec<u64>>>,close:RetainedCloneClose,closing:bool}
impl RetainedCloneEdit<u64,u64> for ScalarEdit{
 type Cursor=ScalarCursor;
 fn preflight(&self,_:&u64,_:HistoryLane)->Result<ArtifactStoreOneItemFootprint,String>{Ok(ArtifactStoreOneItemFootprint{work_items:2,retained_bytes:4096})}
 fn begin_demand(&self)->RetainedCloneBirthDemand{RetainedCloneBirthDemand{capacity_bytes:0,depth:1}}
 fn snapshot_cursor_birth_demand(&self)->RetainedCloneBirthDemand{RetainedCloneBirthDemand{capacity_bytes:0,depth:1}}
 fn begin(&self,g:RetainedCloneGrant)->Result<(Self::Cursor,RetainedCloneProgress),ValueError>{let d=RetirementDemand{copy_bytes:size_of::<ScalarCursor>(),depth:1,..Default::default()};if !retained_clone_grant_admits(g,d){return Err(invalid("scalar edit cursor transfer not funded"));}Ok((ScalarCursor{phase:0,inverse:ManuallyDrop::new(None),close:Default::default(),closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
}
impl RetainedCloneEditCursor<u64,u64> for ScalarCursor{
 fn advance_demands(&self,_:RetainedCloneRef<'_,u64>,_:&u64,_:RetainedCloneRef<'_,u64>,_:usize)->Result<RetirementDemand,ValueError>{Ok(match self.phase{0=>RetirementDemand{copy_bytes:size_of::<Vec<u64>>()+size_of::<u64>(),capacity_bytes:size_of::<u64>(),depth:1,..Default::default()},1=>RetirementDemand{copy_bytes:size_of::<u64>()*2+size_of::<Vec<u64>>(),depth:1,..Default::default()},_=>Default::default()})}
 fn advance(&mut self,b:RetainedCloneRef<'_,u64>,post:&mut u64,m:RetainedCloneRef<'_,u64>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneEditStep,ValueError>{let d=self.advance_demands(b,post,m,body)?;if self.closing||!retained_clone_grant_admits(g,d){return Ok(RetainedCloneEditStep::Progress(Default::default()));}match self.phase{0=>{let mut rows=Vec::new();rows.try_reserve_exact(1).map_err(|_|invalid("scalar inverse allocation failed"))?;rows.push(*b.get());*self.inverse=Some(rows);self.phase=1;},1=>{*post=*m.get();self.phase=2;},_=>return Ok(RetainedCloneEditStep::Complete(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()};Ok(if self.phase==2{RetainedCloneEditStep::Complete(p)}else{RetainedCloneEditStep::Progress(p)})}
 fn take_inverse(&mut self)->Option<Vec<u64>>{self.inverse.take()}
 fn foreign_step_presence(&self)->bool{false}
 fn cancel(&mut self){self.closing=true;}
 fn begin_close(&mut self)->bool{let first=!self.closing;self.closing=true;first}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.close.is_empty(){return self.close.step_granted(g);}if let Some(step)=self.close.begin_granted(&mut self.inverse,g)?{return Ok(step);}Ok(RetainedCloneStep::Complete(Default::default()))}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,b:usize)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,b)?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close.next_owner_demands::<Vec<u64>>(self.inverse.is_some(),&None,4096)?.depth)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.inverse.is_none()&&self.close.is_empty()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn close_typed<T:RetireOwned>(value:T){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty(){return;}let g=grant(owner.next_demand(4096).unwrap());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("typed semantic output did not close");}
#[test]
fn original_semantic_factory_matches_neutral_outputs_and_exact_physical_turns(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🌱️derived/🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter().filter(|case|case["accepted"]==true){for cancel_at in [None,Some(0),Some(1),Some(2),Some(8),Some(16)]{
  let snapshots:Arc<dyn ArtifactOwnedValueRetirementFactory<u64>>=Arc::new(semio_framework_value::retirement::OwnedValueRetirementFactory::<u64>::default());let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<u64>>=Arc::new(semio_framework_value::retirement::OwnedValueRetirementFactory::<u64>::default());
  let factory=RetainedClonePreparationFactory::new(Arc::new(ScalarEdit),Arc::clone(&mutations),Arc::new(semio_framework_value::retirement::SharedValueRetirementFactory::<u64>::default()),64).unwrap();
  let before=case["base"]["n"].as_u64().unwrap();let after=case["after"]["n"].as_u64().unwrap();let mut original=Some(after);let(mut source,_)=ArtifactMutationSource::admit(&mut original,&mutations,grant(ArtifactMutationSource::<u64>::constructor_demand())).unwrap().unwrap();
  let mut input=None;for _ in 0..8{if source.ready(){source.take(&mut input,grant(source.demands(4096).unwrap())).unwrap();break;}let d=source.demands(4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.advance(grant(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
  let address=input.as_ref().unwrap().borrow().unwrap().get()as*const u64;
  let registry=SnapshotReadRegistryHandle::new();let root=Arc::new(before);let lease=registry.try_issue(Arc::clone(&root)).unwrap_or_else(|_|panic!("original read registry"));let context=ArtifactReplayPreparationContext{mode:super::super::ArtifactReplayPreparationMode::Prefix,operation_index:0,generation:7,base_revision:[9;32]};
  let request=ArtifactReplayPreparationRequest{base:SnapshotRead::new(Arc::clone(&root),lease),input:input.take().unwrap(),context,snapshots:Arc::clone(&snapshots),mutations:Arc::clone(&mutations)};
  let mut callback=|_:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|true;let mut original_recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new_retained(&mut callback);control.install_retirement_recipient(&mut original_recipient).unwrap();let g=grant(factory.preparation_birth_demand());let admitted=control.owned_bytes();let((mut cursor,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{control.admit_turn_capacity(g.maximum_capacity_bytes).unwrap();control.charge(g.maximum_capacity_bytes).unwrap();ArtifactReplayPreparationFactory::begin(&factory,request,g).map_err(|(error,_)|error).unwrap()});assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));
  
  let mut ready=false;for turn in 0..10000{if cancel_at==Some(turn){cursor.cancel();break;}let d=cursor.advance_demands(4096).unwrap();let g=grant(d);
   for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let admitted=control.owned_bytes();let(blocked,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(4096,ArtifactStoreOneItemGrant{maximum_items:denied.maximum_items,maximum_copy_bytes:denied.maximum_copy_bytes,maximum_capacity_bytes:denied.maximum_capacity_bytes,maximum_release_bytes:denied.maximum_release_bytes,maximum_depth:denied.maximum_depth},&mut control).unwrap());assert_eq!(control.owned_bytes(),admitted);assert_eq!(blocked,ArtifactReplayPreparationStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
   let admitted=control.owned_bytes();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(4096,ArtifactStoreOneItemGrant{maximum_items:g.maximum_items,maximum_copy_bytes:g.maximum_copy_bytes,maximum_capacity_bytes:g.maximum_capacity_bytes,maximum_release_bytes:g.maximum_release_bytes,maximum_depth:g.maximum_depth},&mut control).unwrap());assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,ArtifactReplayPreparationStep::Prepared(_)){ready=true;break;}
  }
  if cancel_at.is_none(){assert!(ready);let mut result=cursor.take_prepared().unwrap();assert_eq!(**result.next.as_ref().unwrap(),after);assert_eq!(result.inverse.as_ref().unwrap().first(),Some(&before));close_typed(result.next.take().unwrap());close_typed(result.inverse.unwrap());close_typed(result.messages);}
  cursor.cancel();cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let admitted=control.owned_bytes();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.with_retirement(g,|receiving|cursor.close_step(g,receiving)).unwrap());assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());drop(cursor);
  source.begin_close();for _ in 0..10000{if source.terminal_is_empty(){break;}let g=grant(source.close_demand(4096).unwrap());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(source.terminal_is_empty());assert!(!address.is_null());close_typed(root);
 }
 }
 eprintln!("[DEBUG] Actual metadata-free original native factory matched neutral scalar patches with independently paid physical semantic/output/cancellation turns");
}
